const {deviceState,syncDevice}=require('../../utils/page')
const {fetchCatalogue,MODULES}=require('./ieltsPaperService')
const {createPdfDownloadController,initialPdfDownloadState,formatBytes}=require('../../utils/pdfDownload')
const {refreshNativeSession}=require('../../utils/nativeSession')
Page({
 ...require('../../utils/share').public,
 onShareAppMessage(){return{title:'STEMist · 剑雅真题与答案',path:'/bundles/curricula/ieltsPapers',imageUrl:'/design-system/share-card.png'}},
 data:deviceState({loading:true,error:'',books:[],book:0,bookIndex:0,module:'',modules:[{id:'',label:'全部'},...Object.entries(MODULES).map(([id,label])=>({id,label}))],items:[],total:0,page:0,pages:0,pdfDownload:initialPdfDownloadState()}),
 onLoad(options={}){this.__disposed=false;this.__generation=0;this.setData({book:Number(options.book)||0,module:MODULES[options.module]?options.module:''});this.__pdf=createPdfDownloadController({wxApi:wx,isScopeCurrent:scope=>!this.__disposed&&scope===this.scope(),onState:state=>{if(!this.__disposed)this.setData({pdfDownload:state})}});return this.load()},
 scope(){return[this.data.book,this.data.module,this.data.page].join('|')},
 onShow(){syncDevice(this);this.__pdf?.setScope(this.scope());this.__pdf?.resume()},onResize(){syncDevice(this)},onHide(){this.__pdf?.suspend()},onUnload(){this.__disposed=true;this.__generation++;this.__pdf?.dispose()},
 async load(){const generation=++this.__generation;this.setData({loading:true,error:''});try{const c=await fetchCatalogue();if(this.__disposed||generation!==this.__generation)return;this.__catalogue=c;const books=c.books.map(value=>({value,label:'Cambridge '+value})),book=books.some(b=>b.value===this.data.book)?this.data.book:books[0]?.value||0;this.setData({books,book,bookIndex:Math.max(0,books.findIndex(b=>b.value===book)),page:0});this.render()}catch(e){if(!this.__disposed&&generation===this.__generation)this.setData({error:e.message})}finally{if(!this.__disposed&&generation===this.__generation)this.setData({loading:false})}},
 render(){const list=(this.__catalogue?.items||[]).filter(i=>(!this.data.book||i.book===this.data.book)&&(!this.data.module||i.module===this.data.module)),pages=Math.ceil(list.length/12),page=Math.min(this.data.page,Math.max(0,pages-1));this.__pdf?.setScope([this.data.book,this.data.module,page].join('|'));this.setData({page,pages,total:list.length,items:list.slice(page*12,page*12+12).map(i=>({...i,qpMeta:i.qp.pages+' 页 · '+formatBytes(i.qp.bytes),akMeta:i.ak?i.ak.pages+' 页 · '+formatBytes(i.ak.bytes):'',answerNote:i.ak?'':i.answerStatus==='no_unique_answer'?'写作、口语没有唯一标准答案。':'参考答案尚有缺项，暂不提供下载。'}))})},
 chooseBook(e){const index=Number(e.detail.value),book=this.data.books[index];if(!book)return;this.setData({book:book.value,bookIndex:index,page:0});this.render()},
 chooseModule(e){const module=String(e.currentTarget.dataset.module||'');if(module&&!MODULES[module])return;this.setData({module,page:0});this.render()},
 previous(){if(this.data.page>0){this.setData({page:this.data.page-1});this.render();wx.pageScrollTo?.({scrollTop:0,duration:0})}},next(){if(this.data.page+1<this.data.pages){this.setData({page:this.data.page+1});this.render();wx.pageScrollTo?.({scrollTop:0,duration:0})}},
 async openPdf(e){if(this.data.pdfDownload.active||this.__opening)return;const group=this.data.items.find(i=>i.id===e.currentTarget.dataset.id),kind=e.currentTarget.dataset.kind==='ak'?'ak':'qp',file=group?.[kind];if(!file)return;if(!wx.getStorageSync('stemistUser')?.id){this.account();return}const scope=this.scope(),owner=String(wx.getStorageSync('stemistUser')?.id),epoch=wx.getStorageSync('stemistPrivacyEpoch');this.__opening=true;try{await refreshNativeSession();if(this.__disposed||scope!==this.scope()||owner!==String(wx.getStorageSync('stemistUser')?.id)||epoch!==wx.getStorageSync('stemistPrivacyEpoch'))return;this.__pdf.setScope(scope);return await this.__pdf.open({url:file.url,cacheKey:file.sha256,cacheVersion:file.sha256,cacheScope:'identity',ownerKey:file.id,itemId:group.id,label:group.meta+' · '+(kind==='ak'?'参考答案':'题目'),fileName:file.fileName,expectedBytes:file.bytes,sha256:file.sha256,scope})}catch(e){if(!this.__disposed)this.setData({error:e.message})}finally{this.__opening=false}},
 cancel(){this.__pdf?.cancel()},retry(){return this.__pdf?.retry()},toggle(){this.__pdf?.toggleCollapsed()},account(){wx.navigateTo({url:'/pages/account/auth'})},back(){wx.navigateBack({fail:()=>wx.reLaunch({url:'/pages/practice/index?category=ielts'})})},
})
